(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin((x+w1x)*0.035-t*0.5)*8 + Math.cos((y+w1y)*0.03+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.035+t*0.45)*8 + Math.sin((x+w1x)*0.032-t*0.35)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 0.7],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 0.6],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 0.5],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.75],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+1)*40, 0.14, 2.1, 0.65],
    [400+Math.cos(t*0.55+2)*70, 200+Math.sin(t*0.75+4)*50, 0.05, 2.4, 0.85],
    [200+Math.sin(t*0.25+1)*110, 220+Math.cos(t*0.45+3)*70, 0.11, 1.8, 0.55]
  ];
  let aS = 0, iS = 0, wS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    wS += w;
  }
  const act = aS/wS, inh = iS/wS;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = (Math.sin(sx*0.08+sy*0.05+t*1.6) + Math.sin(sx*0.06-sy*0.08+t*2.2))/4;
  const bg = bg1 + bg2*0.5 + Math.sin((sx+sy)*0.12+t*2.5)*0.15 + Math.sin((sx-sy)*0.1-t*2)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.3;
  const sp2 = (Math.sin(dist*0.08-ang*5-t*2.0) + Math.sin(dist*0.065+ang*6-t*1.8))*0.15;
  const spiral = sp1 + sp2;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.25;
  const fine = Math.sin(sx*0.3+sy*0.2-t*3)*Math.sin(sx*0.2-sy*0.3+t*2.5)*0.1;
  const feed = Math.sin(act*1.2 - inh*0.8)*0.15;
  const r1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral + cell + fine + feed)*2.0);
  const r2 = Math.tanh((r1*1.5 + Math.sin(dist*0.03-ang*2+t)*0.4 - cell*0.5)*1.8);
  const blend = r1*0.6 + r2*0.4, v = blend*0.5+0.5;
  const pal = [[5,10,45],[10,35,85],[15,75,120],[20,130,130],[80,170,120],[180,190,80],[220,170,60],[210,110,70],[180,60,75],[120,35,70],[60,20,60],[5,10,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sf = f*f*(3-2*f);
  const lum = 0.85+Math.sin(blend*Math.PI)*0.15;
  const edge = Math.abs(blend)>0.65?1.12:Math.abs(blend)>0.3?1.05:1.0;
  const glow = Math.max(0, 1-dist/300)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge + glow*30)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge + glow*20)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge + glow*40)|0)
  ];
}
